preConditionHook:
// BollingerWidthBelowAverage (Brian's notes ON-64-c, #64): the band width
// (upper - lower = 2 x numDevs x StdDev) is below its own widthLookback-bar
// average -- a low-volatility filter. numDevs cancels, so the test is
// StdDev(close, length) below its widthLookback-bar average.
// StdDev(close, length): the bands' POPULATION deviation, fresh, its mean and
// squares summed NEWEST-FIRST (BollingerBandCross's construction).
sdMean = 0.0;
for (int i = 0; i < (int)length; ++i) {
    sdMean += close[i];
}
sdMean /= (int)length;
sdVal = 0.0;
for (int i = 0; i < (int)length; ++i) {
    double dev = close[i] - sdMean;
    sdVal += dev * dev;
}
sdVal = std::sqrt(sdVal / (int)length);
// EL: average(sdVal, widthLookback) reads the sdVal VARIABLE's own history,
// 0 for every bar before the first evaluated one -- mirrored as a zero-seeded
// ring buffer, re-seeded if the length changes, read NEWEST-FIRST
// (BarRangeAboveStd / AtrAboveAverage are the reference).
if (sdHistory.size() != (std::size_t)(int)widthLookback) {
    sdHistory.assign((std::size_t)(int)widthLookback, 0.0);
    sdCursor = 0;
}
sdHistory[sdCursor] = sdVal;
sdCursor = (sdCursor + 1) % sdHistory.size();
sdAvg = 0.0;
for (std::size_t k = 0; k < sdHistory.size(); ++k) {
    sdAvg += sdHistory[(sdCursor + sdHistory.size() - 1 - k) % sdHistory.size()];
}
sdAvg /= (int)widthLookback;
